function mostHappyCustomers(customers: number[], moody: number[], k: number): number {
  let base = 0;
  for (let i = 0; i < customers.length; i++) if (moody[i] === 0) base += customers[i];
  let best = 0;
  for (let s = 0; s + k <= customers.length; s++) {
    let gain = 0;
    for (let i = s; i < s + k; i++) if (moody[i] === 1) gain += customers[i];
    best = Math.max(best, gain);
  }
  return base + best;
}

