    def mostHappyCustomers(self, customers: List[int], moody: List[int], k: int) -> int:
        base = sum(c for c, m in zip(customers, moody) if m == 0)
        best = 0
        for s in range(len(customers) - k + 1):
            best = max(best, sum(customers[i] for i in range(s, s + k) if moody[i] == 1))
        return base + best

