function mostHappyCustomers(customers: number[], moody: number[], k: number): number {
  let base = 0, gain = 0, best = 0;
  for (let i = 0; i < customers.length; i++) {
    if (moody[i] === 0) base += customers[i];
    else gain += customers[i];
    if (i >= k && moody[i - k] === 1) gain -= customers[i - k];
    if (i >= k - 1) best = Math.max(best, gain);
  }
  return base + best;
}

